"""Compares one change with mock before and after numbers. Returns KEEP or UNDO."""

import json
from pathlib import Path

from agent.config import BOUNCE_RATE_DROP
from agent.schemas import Verdict, VisitorData

FIXTURES = Path(__file__).resolve().parent / "fixtures"
CASES = ("increased", "decreased")


def load_case(name: str) -> tuple[str, VisitorData, VisitorData]:
    """Load one temp angle: the change, the numbers before, and the numbers after."""
    if name not in CASES:
        known = " or ".join(CASES)
        raise RuntimeError(f"Case must be {known}.")
    data = json.loads((FIXTURES / f"{name}.json").read_text())
    if data.get("source") != "mock":
        raise RuntimeError("Expected mock review data.")
    change = data.get("change")
    if not isinstance(change, str) or not change.strip():
        raise RuntimeError("The mock case has no change.")
    return change.strip(), _visitors(data.get("before")), _visitors(data.get("after"))


def decide(change: str, before: VisitorData, after: VisitorData) -> Verdict:
    """KEEP when bounce rate falls by the margin in config. Otherwise UNDO.

    The verdict is what the loop acts on. The same verdict goes back to the Analyst.
    """
    change = change.strip()
    if not change:
        raise RuntimeError("The review has no change to judge.")
    drop = before.bounce_rate - after.bounce_rate
    decision = "KEEP" if drop >= BOUNCE_RATE_DROP else "UNDO"
    return Verdict(
        decision=decision,
        site_check="OK",
        numbers_before=before,
        numbers_after=after,
        reason=_reason(change, before, after, decision, drop),
    )


def verdict_text(verdict: Verdict) -> str:
    return "\n".join(
        [
            f"decision:         {verdict.decision}",
            f"site check:       {verdict.site_check}",
            f"numbers before:   {_numbers(verdict.numbers_before)}",
            f"numbers after:    {_numbers(verdict.numbers_after)}",
            f"reason:           {verdict.reason}",
        ]
    )


def _reason(
    change: str,
    before: VisitorData,
    after: VisitorData,
    decision: str,
    drop: float,
) -> str:
    margin = int(BOUNCE_RATE_DROP * 100)
    moved = (
        f"Mock bounce rate {before.bounce_rate:.0%} -> {after.bounce_rate:.0%}. "
        f"Scroll depth {before.scroll_depth:.0%} -> {after.scroll_depth:.0%}. "
        f"Time on page {before.time_on_page:.1f}s -> {after.time_on_page:.1f}s. "
        f"Pricing page visits {before.pricing_page_visits} -> {after.pricing_page_visits}."
    )
    if decision == "KEEP":
        return (
            f"KEEP. Change: {change}. "
            f"Bounce rate fell by {drop:.0%}, at least {margin} percentage points. "
            + moved
        )
    if drop < 0:
        why = "Bounce rate got worse."
    else:
        why = f"Bounce rate did not fall by at least {margin} percentage points."
    return f"UNDO. Change: {change}. {why} {moved}"


def _numbers(visitors: VisitorData) -> str:
    return (
        f"bounce rate {visitors.bounce_rate:.0%}, "
        f"scroll depth {visitors.scroll_depth:.0%}, "
        f"pricing page visits {visitors.pricing_page_visits}"
    )


def _visitors(raw: object) -> VisitorData:
    if not isinstance(raw, dict):
        raise RuntimeError("Mock review data is missing numbers.")
    return VisitorData(
        bounce_rate=_rate(raw, "bounce_rate"),
        scroll_depth=_rate(raw, "scroll_depth"),
        pricing_page_visits=_count(raw, "pricing_page_visits"),
        time_on_page=_time(raw, "time_on_page"),
        source="mock",
    )


def _rate(raw: dict, key: str) -> float:
    value = raw.get(key)
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise RuntimeError(f"Mock review data is missing {key}.")
    if not 0 <= float(value) <= 1:
        raise RuntimeError(f"{key} must be between 0 and 1.")
    return float(value)


def _count(raw: dict, key: str) -> int:
    value = raw.get(key)
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise RuntimeError(f"Mock review data is missing {key}.")
    return value


def _time(raw: dict, key: str) -> float:
    value = raw.get(key)
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value < 0:
        raise RuntimeError(f"Mock review data is missing {key}.")
    return float(value)

"""Looks at one change and the mock numbers, then returns KEEP or UNDO."""

import neatlogs

from agent.reviewer.verdict import decide, load_case, verdict_text
from agent.schemas import Verdict, VisitorData

__all__ = ["load_case", "review", "verdict_text"]


@neatlogs.span(kind="AGENT", name="reviewer")
def review(change: str, before: VisitorData, after: VisitorData) -> Verdict:
    """Return a verdict the loop can act on. Pass that same verdict back to the Analyst."""
    return decide(change, before, after)

"""Asks the model for two mock outcomes: one improved, one not."""

import json
import re
from pathlib import Path

import neatlogs
from openai import OpenAI

from agent.builder.edit import provider_settings
from agent.config import BOUNCE_RATE_DROP, REPO_ROOT
from agent.schemas import VisitorData

FIXTURES = Path(__file__).resolve().parent / "fixtures"
CASES = ("increased", "decreased")
DEFAULT_CHANGE = (
    "Add a short benefit-focused subheadline and three feature bullets on the homepage."
)


def generate_outcomes(change: str, before: VisitorData) -> dict[str, VisitorData]:
    """Ask the model for both outcomes, check them, and write the two JSON files."""
    change = change.strip()
    if not change:
        raise RuntimeError("The simulator has no change to react to.")
    mistake = ""
    last_error = "The model did not return usable mock numbers."
    for _ in range(2):
        try:
            raw = _ask(change, before, mistake)
            outcomes = _outcomes(raw, before)
        except RuntimeError as error:
            last_error = str(error)
            mistake = last_error
            continue
        _write(change, before, outcomes)
        return outcomes
    raise RuntimeError(last_error)


def _ask(change: str, before: VisitorData, mistake: str) -> dict:
    margin = int(BOUNCE_RATE_DROP * 100)
    api_key, base_url, model = provider_settings()
    client = neatlogs.wrap(OpenAI(api_key=api_key, base_url=base_url))
    correction = f"\n\nYour last answer was rejected: {mistake}" if mistake else ""
    response = client.chat.completions.create(
        model=model,
        temperature=0.2,
        response_format={"type": "json_object"},
        messages=[
            {
                "role": "system",
                "content": (
                    "You simulate mock visitors after one website change. "
                    "Return JSON only, with this shape: "
                    '{"increased":{"bounce_rate":0.62,"scroll_depth":0.34,'
                    '"pricing_page_visits":7,"time_on_page":18.4},'
                    '"decreased":{"bounce_rate":0.79,"scroll_depth":0.06,'
                    '"pricing_page_visits":1,"time_on_page":4.2}}. '
                    "bounce_rate and scroll_depth are fractions from 0 to 1, not percents. "
                    "time_on_page is seconds. pricing_page_visits is a whole number. "
                    f"increased must drop bounce_rate by at least {margin} percentage points "
                    "and must raise scroll depth, time on page, and pricing visits. "
                    "decreased must raise bounce_rate and must lower the other three. "
                    "These numbers are mock."
                ),
            },
            {
                "role": "user",
                "content": (
                    f"Change: {change}\n"
                    f"Before: bounce_rate {before.bounce_rate}, "
                    f"scroll_depth {before.scroll_depth}, "
                    f"pricing_page_visits {before.pricing_page_visits}, "
                    f"time_on_page {before.time_on_page}."
                    + correction
                ),
            },
        ],
    )
    text = (response.choices[0].message.content or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text)
        text = re.sub(r"\s*```$", "", text)
    try:
        data = json.loads(text)
    except json.JSONDecodeError as error:
        raise RuntimeError("The model did not return JSON.") from error
    if not isinstance(data, dict):
        raise RuntimeError("The model did not return the two outcomes.")
    return data


def _outcomes(raw: dict, before: VisitorData) -> dict[str, VisitorData]:
    increased = _visitors(raw.get("increased"))
    decreased = _visitors(raw.get("decreased"))
    _check_increased(before, increased)
    _check_decreased(before, decreased)
    return {"increased": increased, "decreased": decreased}


def _check_increased(before: VisitorData, after: VisitorData) -> None:
    if before.bounce_rate - after.bounce_rate < BOUNCE_RATE_DROP:
        raise RuntimeError(
            "increased must drop bounce_rate by at least "
            f"{int(BOUNCE_RATE_DROP * 100)} percentage points."
        )
    if not (
        after.scroll_depth > before.scroll_depth
        and after.time_on_page > before.time_on_page
        and after.pricing_page_visits > before.pricing_page_visits
    ):
        raise RuntimeError("increased must raise scroll, time on page, and pricing visits.")


def _check_decreased(before: VisitorData, after: VisitorData) -> None:
    if after.bounce_rate <= before.bounce_rate:
        raise RuntimeError("decreased must raise bounce_rate.")
    if not (
        after.scroll_depth < before.scroll_depth
        and after.time_on_page < before.time_on_page
        and after.pricing_page_visits < before.pricing_page_visits
    ):
        raise RuntimeError("decreased must lower scroll, time on page, and pricing visits.")


def _write(change: str, before: VisitorData, outcomes: dict[str, VisitorData]) -> None:
    FIXTURES.mkdir(parents=True, exist_ok=True)
    for name, after in outcomes.items():
        payload = {
            "source": "mock",
            "change": change,
            "before": _fields(before),
            "after": _fields(after),
        }
        path = FIXTURES / f"{name}.json"
        path.write_text(json.dumps(payload, indent=2) + "\n")


def fixture_path(name: str) -> Path:
    return (FIXTURES / f"{name}.json").relative_to(REPO_ROOT)


def _fields(visitors: VisitorData) -> dict:
    return {
        "bounce_rate": visitors.bounce_rate,
        "scroll_depth": visitors.scroll_depth,
        "pricing_page_visits": visitors.pricing_page_visits,
        "time_on_page": visitors.time_on_page,
    }


def _visitors(raw: object) -> VisitorData:
    if not isinstance(raw, dict):
        raise RuntimeError("One outcome is missing its numbers.")
    return VisitorData(
        bounce_rate=_rate(raw, "bounce_rate"),
        scroll_depth=_rate(raw, "scroll_depth"),
        pricing_page_visits=_count(raw, "pricing_page_visits"),
        time_on_page=_time(raw, "time_on_page"),
        source="mock",
