"""The folder inside a repo the Analyst and Builder are allowed to edit."""

from pathlib import Path

from agent.config import REPO_ROOT

TEXT_SUFFIXES = {".html", ".css", ".js", ".jsx", ".ts", ".tsx", ".svg", ".txt", ".md"}
SKIP_DIRS = {".git", "node_modules", "venv", ".venv", ".next", "dist", "build"}
BLOCKED_NAMES = {
    "package.json",
    "package-lock.json",
    "yarn.lock",
    "pnpm-lock.yaml",
    "bun.lock",
}


def source_root(folder: str) -> Path:
    """Resolve sourceFolder from the project. '.' is the repository root."""
    raw = folder.strip().replace("\\", "/")
    if raw in {"", "."}:
        return REPO_ROOT.resolve()
    if raw.startswith("/") or ".." in Path(raw).parts:
        raise RuntimeError("sourceFolder must stay inside the repository.")
    path = (REPO_ROOT / raw.strip("/")).resolve()
    root = REPO_ROOT.resolve()
    if path != root and root not in path.parents:
        raise RuntimeError("sourceFolder must stay inside the repository.")
    if not path.is_dir():
        raise RuntimeError(f"{raw} is not a folder in the repository.")
    return path


def folder_label(folder: str) -> str:
    raw = folder.strip().replace("\\", "/")
    if raw in {"", "."}:
        return "the repository root"
    return raw.strip("/") + "/"


def list_source_files(root: Path) -> list[Path]:
    if not root.is_dir():
        raise RuntimeError(f"{root.name} is not a folder in the repository.")
    files = [
        path
        for path in sorted(root.rglob("*"))
        if path.is_file()
        and path.suffix.lower() in TEXT_SUFFIXES
        and not _skipped(path, root)
    ]
    if not files:
        raise RuntimeError(f"{folder_name(root)} has no source files to edit.")
    return files


def read_source(root: Path) -> str:
    parts: list[str] = []
    for path in list_source_files(root):
        relative = path.relative_to(REPO_ROOT).as_posix()
        parts.append(f"--- {relative} ---\n{path.read_text()}")
    return "\n\n".join(parts)


def resolve_in_source(raw: str, root: Path) -> Path:
    """Accept a repo path or a path relative to the source folder."""
    raw = raw.strip().replace("\\", "/").strip("/")
    if not raw or raw.startswith("/") or ".." in Path(raw).parts:
        raise RuntimeError(f"Refusing path: {raw}")
    repo = REPO_ROOT.resolve()
    root = root.resolve()
    from_repo = (repo / raw).resolve()
    from_root = (root / raw).resolve()
    if _inside(from_repo, root):
        path = from_repo
    elif _inside(from_root, root):
        path = from_root
    else:
        raise RuntimeError(f"Refusing a file outside {folder_name(root)}: {raw}")
    if path.name in BLOCKED_NAMES:
        raise RuntimeError(f"Refusing {path.name}. Do not change dependencies.")
    return path


def folder_name(root: Path) -> str:
    root = root.resolve()
    repo = REPO_ROOT.resolve()
    if root == repo:
        return "the repository root"
    return root.relative_to(repo).as_posix() + "/"


def _inside(path: Path, root: Path) -> bool:
    return path == root or root in path.parents


def _skipped(path: Path, root: Path) -> bool:
    relative = path.relative_to(root)
    return any(part in SKIP_DIRS for part in relative.parts)

"""Loads the signed-in user's project and GitHub installation from Firestore."""

import os
from dataclasses import dataclass

from agent.source import folder_label

FRAMEWORKS = {
    "next": "Next.js",
    "nuxt": "Nuxt",
    "sveltekit": "SvelteKit",
    "remix": "Remix",
    "astro": "Astro",
    "gatsby": "Gatsby",
    "angular": "Angular",
    "cra": "Create React App",
    "vite": "Vite",
    "vue": "Vue",
    "svelte": "Svelte",
    "html": "HTML",
    "other": "a simple site",
}


@dataclass
class Project:
    user_id: str
    analytics_provider: str
    goal: str
    repository: str
    branch: str
    framework: str
    source_folder: str
    installation_id: int
    account_login: str

    def root_label(self) -> str:
        return folder_label(self.source_folder)

    def framework_label(self) -> str:
        return FRAMEWORKS.get(self.framework, self.framework or "a simple site")


def load_project() -> Project:
    """Read projects and githubInstallations for PROJECT_USER_ID."""
    user_id = os.getenv("PROJECT_USER_ID", "").strip()
    if not user_id:
        raise RuntimeError("Set PROJECT_USER_ID in agent/.env.")

    client = _client()
    projects = list(
        client.collection("projects").where("userId", "==", user_id).limit(1).stream()
    )
    if not projects:
        raise RuntimeError(f"No project is saved for {user_id}.")

    data = projects[0].to_dict() or {}
    installation = client.collection("githubInstallations").document(user_id).get()
    install = installation.to_dict() if installation.exists else None
    if not install:
        raise RuntimeError(f"No GitHub installation is saved for {user_id}.")

    project = _project(user_id, data)
    saved_id = _installation_id(install.get("installationId"))
    if saved_id != project.installation_id:
        raise RuntimeError("The GitHub installation does not match the project.")
    if str(install.get("accountLogin") or "") != project.account_login:
        raise RuntimeError("The GitHub account does not match the project.")
    return project


def _project(user_id: str, data: dict) -> Project:
    repository = _text(data, "repository")
    branch = _text(data, "branch")
    source_folder = str(data.get("sourceFolder") or "").strip()
    if not source_folder:
        raise RuntimeError("The project has no sourceFolder.")
    goal = _text(data, "goal")
    return Project(
        user_id=user_id,
        analytics_provider=_text(data, "analyticsProvider"),
        goal=goal,
        repository=repository,
        branch=branch,
        framework=str(data.get("framework") or "other").strip() or "other",
        source_folder=source_folder,
        installation_id=_installation_id(data.get("installationId")),
        account_login=_text(data, "accountLogin"),
    )


def _client():
    from google.cloud import firestore
    from google.oauth2 import service_account

    project_id = os.getenv("FIREBASE_PROJECT_ID", "").strip()
    client_email = os.getenv("FIREBASE_CLIENT_EMAIL", "").strip()
    private_key = _private_key(os.getenv("FIREBASE_PRIVATE_KEY", ""))
    if not project_id or not client_email or "BEGIN" not in private_key:
        raise RuntimeError(
            "Set FIREBASE_PROJECT_ID, FIREBASE_CLIENT_EMAIL, and "
            "FIREBASE_PRIVATE_KEY in agent/.env."
        )

    credentials = service_account.Credentials.from_service_account_info(
        {
            "type": "service_account",
            "project_id": project_id,
            "private_key": private_key,
            "client_email": client_email,
            "token_uri": "https://oauth2.googleapis.com/token",
        }
    )
    return firestore.Client(project=project_id, credentials=credentials)


def _private_key(raw: str) -> str:
    key = raw.strip()
    if (key.startswith('"') and key.endswith('"')) or (
        key.startswith("'") and key.endswith("'")
    ):
        key = key[1:-1]
    return key.replace("\\n", "\n")


def _text(data: dict, key: str) -> str:
    value = data.get(key)
    if not isinstance(value, str) or not value.strip():
        raise RuntimeError(f"The project is missing {key}.")
    return value.strip()


def _installation_id(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise RuntimeError("The project is missing installationId.")
    return value

