def open_repo(project: Project, REDACTED: str) -> RepoSandbox:
    """Create a sandbox, clone the saved branch, and return it.

    The caller deletes the sandbox when the pull request is open.
    """
    if not os.getenv("DAYTONA_API_KEY", "").strip():
        raise RuntimeError("Set DAYTONA_API_KEY in agent/.env before opening a sandbox.")

    REDACTED = REDACTED.strip()
    if not REDACTED:
        raise RuntimeError("A GitHub REDACTED is required to clone the repo.")

    owner, name = project.repository.split("/", 1)
    daytona = _client()
    sandbox = daytona.create()
    try:
        sandbox.git.clone(
            url=f"https://github.com/{owner}/{name}.git",
            path=REPO_DIR,
            branch=project.branch,
            username="x-access-REDACTED",
            password=REDACTED,
        )
    except Exception:
        daytona.delete(sandbox)
        raise

    return RepoSandbox(sandbox=sandbox, path=REPO_DIR)


