  type RunRecord,
} from "@/lib/db/schema/run";

export function RunsPage() {
  const router = useRouter();
  const [runs, setRuns] = useState<RunRecord[]>([]);
  const [error, setError] = useState("");
  const [pending, setPending] = useState<RunCase | null>(null);
  const locked = activeRunId(runs);

  useEffect(() => {
    let stopped = false;
    let timer = 0;

    async function load() {
      const response = await fetch("/api/runs");
      const body = await response.json().catch(() => null);
      if (stopped) return;
      if (!response.ok) {
        setError(body?.error ?? "Could not load runs.");
        return;
      }
      const next = Array.isArray(body?.runs) ? (body.runs as RunRecord[]) : [];
      setRuns(next);
      setError("");
      if (next.some((run) => isActiveRun(run.status))) {
        timer = window.setTimeout(load, 2000);
      }
    }

    void load();
    return () => {
      stopped = true;
      window.clearTimeout(timer);
    };
  }, [locked]);

  async function start(runCase: RunCase) {
    setPending(runCase);
    setError("");
    const response = await fetch("/api/runs", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ case: runCase }),
    });
    const body = await response.json().catch(() => null);
    setPending(null);
    if (!response.ok) {
      setError(body?.error ?? "Could not start the run.");
      if (typeof body?.runId === "string" && body.runId) {
        router.push(`/dashboard/runs/${body.runId}`);
      }
      return;
    }
    router.push(`/dashboard/runs/${body.id}`);
  }

  return (
    <main className="flex flex-1 flex-col gap-10 px-6 pt-2 pb-12 md:px-8">
      <PageHeading
        eyebrow="ONE RUN AT A TIME"
        title="Runs"
        description="Start a round, follow each step, and come back to what the agent saved."
        action={
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={Boolean(locked || pending)}
              onClick={() => start("decreased")}
            >
              {pending === "decreased" ? "Starting" : "Decreased"}
            </Button>
            <Button
              disabled={Boolean(locked || pending)}
              onClick={() => start("increased")}
            >
              {pending === "increased" ? "Starting" : "Increased"}
            </Button>
          </div>
        }
      />

      {error ? <p className="text-sm text-destructive">{error}</p> : null}
      {locked ? (
        <p className="text-sm text-muted-foreground">
          A run is already in progress.{" "}
          <Link className="text-foreground underline" href={`/dashboard/runs/${locked}`}>
            Open it
          </Link>
        </p>
      ) : null}

      {runs.length === 0 ? (
        <p className="text-sm text-muted-foreground">No runs yet.</p>
      ) : (
        <ol>
          {runs.map((run) => (
            <li key={run.id} className="border-b border-border py-3.5">
              <Link href={`/dashboard/runs/${run.id}`} className="flex items-baseline justify-between gap-4">
                <span className="text-sm">
                  {run.case === "increased" ? "Increased" : "Decreased"}
                  <span className="ml-2 text-muted-foreground">{run.repository}</span>
                </span>
                <span className="text-xs text-muted-foreground">
                  {label(run.status)}
                  {run.createdAt ? ` · ${when(run.createdAt)}` : ""}
                </span>
              </Link>
            </li>
          ))}
        </ol>
      )}
    </main>
  );
}

function label(status: RunRecord["status"]) {
  if (status === "queued") return "Queued";
  if (status === "running") return "Running";
  if (status === "kept") return "Kept";
  if (status === "undone") return "Undone";
  return "Failed";
}

function when(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString();
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { PageHeading } from "@/components/dashboard/page-heading";
import {
  isActiveRun,
  runStepOrder,
  type RunRecord,
  type RunStep,
} from "@/lib/db/schema/run";
import { cn } from "@/lib/utils";

export function RunDetail({ id }: { id: string }) {
  const [run, setRun] = useState<RunRecord | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    let stopped = false;
    let timer = 0;

    async function load() {
      const response = await fetch(`/api/runs/${id}`);
      const body = await response.json().catch(() => null);
      if (stopped) return;
      if (!response.ok) {
        setError(body?.error ?? "Could not load this run.");
        return;
      }
      const next = body?.run as RunRecord;
      setRun(next);
      setError("");
      if (isActiveRun(next.status)) {
        timer = window.setTimeout(load, 2000);
      }
    }

    void load();
    return () => {
      stopped = true;
      window.clearTimeout(timer);
    };
  }, [id]);

  const saved = new Map(run?.steps.map((step) => [step.id, step]));

  return (
    <main className="flex flex-1 flex-col gap-10 px-6 pt-2 pb-12 md:px-8">
      <PageHeading
        eyebrow={run ? run.id : "RUN"}
        title={run ? title(run) : "Run"}
        description={
          run
            ? `${run.repository} · ${run.branch} · ${run.sourceFolder}`
            : "Loading this run."
        }
        action={
          <Link href="/dashboard/runs" className="text-sm text-muted-foreground">
            All runs
          </Link>
        }
      />

      {error ? <p className="text-sm text-destructive">{error}</p> : null}

      <ol>
        {runStepOrder.map((item) => {
          const step = saved.get(item.id);
          const state = stepState(run, item.id, step);
          return (
            <li
              key={item.id}
              className={cn(
                "border-b border-border py-3.5",
                state === "pending" && "text-muted-foreground",
              )}
            >
              <p className="text-sm">
                {step?.title || item.title}
                <span className="ml-2 text-xs text-muted-foreground">{state}</span>
              </p>
              {step?.detail ? (
                <p className="mt-1 text-xs whitespace-pre-wrap text-muted-foreground">
                  {step.detail}
                </p>
              ) : null}
            </li>
          );
        })}
      </ol>

      {run?.plan ? (
        <section>
          <h2 className="text-sm font-medium">Plan</h2>
          <p className="mt-2 text-sm">{run.plan.change}</p>
          <p className="mt-1 text-xs text-muted-foreground">{run.plan.problem}</p>
          <p className="mt-1 text-xs text-muted-foreground">{run.plan.file}</p>
        </section>
      ) : null}

      {run?.verdict ? (
        <section>
          <h2 className="text-sm font-medium">{run.verdict.decision}</h2>
          <p className="mt-2 text-sm whitespace-pre-wrap">{run.verdict.reason}</p>
        </section>
      ) : null}

      <div className="flex flex-col gap-2 text-sm">
        <UrlLink label="Pull request" url={run?.pullRequestUrl ?? ""} />
        <UrlLink label="Revert pull request" url={run?.revertPullRequestUrl ?? ""} />
      </div>

      {run?.error ? <p className="text-sm text-destructive">{run.error}</p> : null}
    </main>
  );
}

function stepState(
  run: RunRecord | null,
  id: string,
  step: RunStep | undefined,
) {
  if (step) return "done";
  if (!run || !isActiveRun(run.status)) return "pending";
  const firstMissing = runStepOrder.find((item) => !run.steps.some((saved) => saved.id === item.id));
  return firstMissing?.id === id ? "current" : "pending";
}

function title(run: RunRecord) {
  const name = run.case === "increased" ? "Increased" : "Decreased";
  if (run.status === "kept") return `${name} · kept`;
  if (run.status === "undone") return `${name} · undone`;
  if (run.status === "failed") return `${name} · failed`;
  if (run.status === "running") return `${name} · running`;
  return `${name} · queued`;
}

function UrlLink({ label, url }: { label: string; url: string }) {
  if (!url.startsWith("https://")) return null;
  return (
    <a className="underline" href={url} rel="noreferrer" target="_blank">
      {label}
    </a>
  );
}

