"""Mints a short-lived GitHub App installation token for git and pull requests."""

import base64
import json
import os
import time
import urllib.error
import urllib.request

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding


def installation_token(installation_id: int) -> str:
    """Ask GitHub for a token that can push and open pull requests for this install."""
    if installation_id <= 0:
        raise RuntimeError("The project is missing installationId.")

    request = urllib.request.Request(
        f"https://api.github.com/app/installations/{installation_id}/access_tokens",
        data=b"{}",
        method="POST",
        headers={
            "Accept": "application/vnd.github+json",
            "Authorization": f"Bearer {_app_jwt()}",
            "User-Agent": "friction-fixer",
            "X-GitHub-Api-Version": "2022-11-28",
            "Content-Type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            body = json.loads(response.read().decode())
    except urllib.error.HTTPError as error:
        detail = error.read().decode(errors="replace")
        message = _github_message(detail) or error.reason
        raise RuntimeError(
            "GitHub refused an installation token. "
            "The app needs Contents and Pull requests set to Read and write. "
            f"{message}"
        ) from error
    except urllib.error.URLError as error:
        raise RuntimeError(f"GitHub could not be reached. {error.reason}") from error

    token = body.get("token") if isinstance(body, dict) else None
    if not isinstance(token, str) or not token.strip():
        raise RuntimeError("GitHub did not return an installation token.")
    return token.strip()


def _app_jwt() -> str:
    app_id = os.getenv("GITHUB_APP_ID", "").strip()
    private_key = _private_key(os.getenv("GITHUB_APP_PRIVATE_KEY", ""))
    if not app_id or "BEGIN" not in private_key:
        raise RuntimeError(
            "Set GITHUB_APP_ID and GITHUB_APP_PRIVATE_KEY on the agent. "
            "Use the same values as the website."
        )

    now = int(time.time())
    header = _b64(json.dumps({"alg": "RS256", "typ": "JWT"}, separators=(",", ":")).encode())
    payload = _b64(
        json.dumps(
            {"iat": now - 60, "exp": now + 9 * 60, "iss": app_id},
            separators=(",", ":"),
        ).encode()
    )
    signing_input = f"{header}.{payload}".encode()
    key = serialization.load_pem_private_key(private_key.encode(), password=None)
    signature = key.sign(signing_input, padding.PKCS1v15(), hashes.SHA256())
    return f"{header}.{payload}.{_b64(signature)}"


def _private_key(raw: str) -> str:
    key = raw.strip()
    if (key.startswith('"') and key.endswith('"')) or (
        key.startswith("'") and key.endswith("'")
    ):
        key = key[1:-1]
    return key.replace("\\n", "\n")


def _b64(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).rstrip(b"=").decode()


def _github_message(raw: str) -> str:
    try:
        body = json.loads(raw)
    except json.JSONDecodeError:
        return raw.strip()
    message = body.get("message") if isinstance(body, dict) else None
    return message.strip() if isinstance(message, str) else ""

"""Reads earlier runs so the next change starts from the latest saved numbers."""

from datetime import datetime

from agent.project import _client
from agent.schemas import Verdict, VisitorData


def load_saved(user_id: str, run_id: str) -> tuple[VisitorData | None, list[Verdict]]:
    """Return the latest mock numbers and the past verdicts, oldest first.

    A first project has neither. A kept run continues from its after numbers.
    An undone run continues from its before numbers, because that change was reverted.
    A run that stopped early still contributes its before numbers when nothing newer settled.
    """
    docs = list(
        _client().collection("runs").where("userId", "==", user_id).stream()
    )
    rows = []
    for doc in docs:
        if doc.id == run_id:
            continue
        data = doc.to_dict() or {}
        if data.get("status") in {"queued", "running"}:
            continue
        rows.append(data)
    rows.sort(key=_stamp)

    history: list[Verdict] = []
    for data in rows:
        verdict = _verdict(data)
        if verdict:
            history.append(verdict)
    return _baseline(rows), history


def _baseline(rows: list[dict]) -> VisitorData | None:
    if not rows:
        return None
    latest = rows[-1]
    before = _visitors(latest.get("before"))
    after = _visitors(latest.get("after"))
    status = latest.get("status")
    if status == "kept" and after:
        return after
    if status == "undone" and before:
        return before
    return before or after


def _verdict(data: dict) -> Verdict | None:
    raw = data.get("verdict")
    if not isinstance(raw, dict):
        return None
    decision = raw.get("decision")
    if decision not in {"KEEP", "UNDO"}:
        return None
    before = _visitors(data.get("before"))
    after = _visitors(data.get("after"))
    if not before or not after:
        return None
    reason = raw.get("reason")
    site_check = raw.get("siteCheck")
    return Verdict(
        decision=decision,
        site_check=site_check.strip() if isinstance(site_check, str) and site_check.strip() else "OK",
        numbers_before=before,
        numbers_after=after,
        reason=reason.strip() if isinstance(reason, str) else "",
    )


def _visitors(value: object) -> VisitorData | None:
    if not isinstance(value, dict):
        return None
    bounce = value.get("bounceRate")
    scroll = value.get("scrollDepth")
    seconds = value.get("timeOnPage")
    visits = value.get("pricingPageVisits")
    if not all(isinstance(item, (int, float)) and not isinstance(item, bool) for item in (bounce, scroll, seconds, visits)):
        return None
    return VisitorData(
        bounce_rate=float(bounce),
        scroll_depth=float(scroll),
        time_on_page=float(seconds),
        pricing_page_visits=int(visits),
    )


def _stamp(data: dict) -> str:
    for key in ("finishedAt", "startedAt", "createdAt"):
        value = data.get(key)
        if isinstance(value, datetime):
            return value.isoformat()
        if isinstance(value, str) and value:
            return value
    return ""

