import { siteUrl } from "@/lib/seo";

export const POSTHOG_OAUTH_ORIGIN = "https://oauth.posthog.com";

export const POSTHOG_SCOPES = [
  "project:read",
  "query:read",
  "web_analytics:read",
  "user:read",
] as const;

export const POSTHOG_MESSAGE = "ff-posthog";

const REDIRECT_ORIGINS = [
  siteUrl,
  "http://localhost:3000",
  "http://127.0.0.1:3000",
];

export function posthogClientId() {
  return `${siteUrl}/api/posthog/client`;
}

export function posthogRedirectUri(origin: string) {
  return `${origin}/api/posthog/callback`;
}

export function posthogRedirectAllowed(origin: string) {
  return REDIRECT_ORIGINS.includes(origin);
}

export function posthogAuthorizeUrl(input: {
  redirectUri: string;
  state: string;
  codeChallenge: string;
}) {
  const url = new URL("/oauth/authorize/", POSTHOG_OAUTH_ORIGIN);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("client_id", posthogClientId());
  url.searchParams.set("redirect_uri", input.redirectUri);
  url.searchParams.set("scope", POSTHOG_SCOPES.join(" "));
  url.searchParams.set("state", input.state);
  url.searchParams.set("code_challenge", input.codeChallenge);
  url.searchParams.set("code_challenge_method", "S256");
  url.searchParams.set("required_access_level", "project");
  return url;
}

import { createHash, randomBytes } from "node:crypto";

export function createCodeVerifier() {
  return randomBytes(32).toString("base64url");
}

export function codeChallenge(verifier: string) {
  return createHash("sha256").update(verifier).digest("base64url");
}

import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";

export const POSTHOG_STATE_COOKIE = "ff-posthog-state";

type StatePayload = {
  userId: string;
  nonce: string;
  verifier: string;
  redirectUri: string;
  exp: number;
};

export function posthogStateCookieOptions() {
  return {
    path: "/api/posthog",
    httpOnly: true,
    sameSite: "lax" as const,
    secure: process.env.NODE_ENV === "production",
    maxAge: 10 * 60,
  };
}

export function createPosthogState(
  userId: string,
  verifier: string,
  redirectUri: string,
) {
  const payload: StatePayload = {
    userId,
    nonce: randomBytes(16).toString("base64url"),
    verifier,
    redirectUri,
    exp: Date.now() + 10 * 60 * 1000,
  };
  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
  return `${body}.${sign(body)}`;
}

export function readPosthogState(state: string, userId: string) {
  const [body, signature, extra] = state.split(".");
  if (!body || !signature || extra) return null;
  if (!safeEqual(signature, sign(body))) return null;

  try {
    const payload = JSON.parse(
      Buffer.from(body, "base64url").toString(),
    ) as Partial<StatePayload>;
    if (payload.userId !== userId) return null;
    if (typeof payload.exp !== "number" || payload.exp < Date.now()) return null;
    if (typeof payload.verifier !== "string" || !payload.verifier) return null;
    if (typeof payload.redirectUri !== "string" || !payload.redirectUri) {
      return null;
    }
    return {
      verifier: payload.verifier,
      redirectUri: payload.redirectUri,
    };
  } catch {
    return null;
  }
}

function sign(body: string) {
  const secret = process.env.COOKIE_SECRET_KEY;
  if (!secret) throw new Error("Missing COOKIE_SECRET_KEY.");
  return createHmac("sha256", secret).update(body).digest("base64url");
}

function safeEqual(a: string, b: string) {
  const left = Buffer.from(a);
  const right = Buffer.from(b);
  return left.length === right.length && timingSafeEqual(left, right);
}

export type PosthogConnectionRecord = {
  userId: string;
  projectId: string;
  projectName: string;
  apiHost: string;
  refreshToken: string;
  createdAt: unknown;
  updatedAt: unknown;
};

export type PosthogConnectionStatus =
  | { connected: false }
  | { connected: true; projectId: string; projectName: string; apiHost: string };

import { FieldValue } from "firebase-admin/firestore";
import { COLLECTIONS } from "@/lib/db/collections";
import { db } from "@/lib/db/firebase";
import type {
  PosthogConnectionRecord,
  PosthogConnectionStatus,
} from "@/lib/db/schema/posthog-connection";

export async function getPosthogConnection(userId: string) {
  const snap = await db()
    .collection(COLLECTIONS.POSTHOG_CONNECTIONS)
    .doc(userId)
    .get();
  if (!snap.exists) return null;
  const data = snap.data();
  if (!data) return null;
  const projectId = text(data.projectId);
  const apiHost = text(data.apiHost);
  const refreshToken = text(data.refreshToken);
  if (!projectId || !apiHost || !refreshToken) return null;
  const record: PosthogConnectionRecord = {
    userId,
    projectId,
    projectName: text(data.projectName) || "PostHog project",
    apiHost,
    refreshToken,
    createdAt: data.createdAt,
    updatedAt: data.updatedAt,
  };
  return record;
}

export function posthogStatus(
  record: PosthogConnectionRecord | null,
): PosthogConnectionStatus {
  if (!record) return { connected: false };
  return {
    connected: true,
    projectId: record.projectId,
    projectName: record.projectName,
    apiHost: record.apiHost,
  };
}

export async function savePosthogConnection(input: {
  userId: string;
  projectId: string;
  projectName: string;
  apiHost: string;
  refreshToken: string;
}) {
  const ref = db()
    .collection(COLLECTIONS.POSTHOG_CONNECTIONS)
    .doc(input.userId);
  const snap = await ref.get();
  await ref.set({
    userId: input.userId,
    projectId: input.projectId,
    projectName: input.projectName,
    apiHost: input.apiHost,
    refreshToken: input.refreshToken,
    createdAt: snap.exists
      ? (snap.get("createdAt") ?? FieldValue.serverTimestamp())
      : FieldValue.serverTimestamp(),
    updatedAt: FieldValue.serverTimestamp(),
  });
}

export async function deletePosthogConnection(userId: string) {
  await db().collection(COLLECTIONS.POSTHOG_CONNECTIONS).doc(userId).delete();
}

function text(value: unknown) {
  return typeof value === "string" ? value.trim() : "";
}

import { POSTHOG_OAUTH_ORIGIN, posthogClientId } from "@/lib/posthog/config";

const API_HOSTS = ["https://us.posthog.com", "https://eu.posthog.com"];

type TokenResponse = {
  access_token?: string;
  refresh_token?: string;
  error?: string;
  error_description?: string;
};

export async function exchangePosthogCode(input: {
  code: string;
  redirectUri: string;
  verifier: string;
}) {
  return posthogToken({
    grant_type: "authorization_code",
    code: input.code,
    redirect_uri: input.redirectUri,
    code_verifier: input.verifier,
    client_id: posthogClientId(),
  });
}

export async function findPosthogProject(accessToken: string) {
  let lastError = "PostHog did not return a project.";
  for (const host of API_HOSTS) {
    const response = await fetch(`${host}/api/projects/`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (response.status === 401 || response.status === 403) continue;
    const body = (await response.json().catch(() => null)) as
      | { results?: unknown; detail?: unknown }
      | unknown[]
      | null;
    if (!response.ok) {
      lastError = messageFrom(body) || lastError;
      continue;
    }
    const rows = Array.isArray(body)
      ? body
      : Array.isArray(body?.results)
        ? body.results
        : [];
    const project = rows.find(
      (row) =>
        row &&
        typeof row === "object" &&
        "id" in row &&
        (typeof row.id === "number" || typeof row.id === "string"),
    ) as { id: number | string; name?: string } | undefined;
    if (!project) continue;
    return {
      projectId: String(project.id),
      projectName: project.name?.trim() || "PostHog project",
      apiHost: host,
    };
  }
  throw new Error(lastError);
}

async function posthogToken(fields: Record<string, string>) {
  const response = await fetch(`${POSTHOG_OAUTH_ORIGIN}/oauth/token/`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(fields),
  });
  const body = (await response.json().catch(() => null)) as TokenResponse | null;
  if (!response.ok || !body?.access_token || !body.refresh_token) {
    throw new Error(
      body?.error_description || body?.error || "PostHog did not return a token.",
    );
  }
  return { accessToken: body.access_token, refreshToken: body.refresh_token };
}

function messageFrom(body: unknown) {
  if (!body || typeof body !== "object" || Array.isArray(body)) return "";
  const detail = "detail" in body ? body.detail : null;
  return typeof detail === "string" ? detail : "";
}

