export type RunGroup = {
  projectId: string;
  repository: string;
  branch: string;
  sourceFolder: string;
  connectedAt: string | null;
  current: boolean;
  runs: RunRecord[];
};

export function groupRuns(
  runs: RunRecord[],
  current?: { id: string; createdAt: string | null } | null,
): RunGroup[] {
  const byProject = new Map<string, RunRecord[]>();
  for (const run of runs) {
    const key = run.projectId || run.id;
    const list = byProject.get(key);
    if (list) list.push(run);
    else byProject.set(key, [run]);
  }

  const groups = [...byProject.entries()].map(([projectId, items]) => {
    const sample = items[0];
    const currentProject = current?.id === projectId;
    return {
      projectId,
      repository: sample?.repository || "Repository",
      branch: sample?.branch || "",
      sourceFolder: sample?.sourceFolder || "",
      connectedAt: currentProject
        ? current?.createdAt || earliest(items)
        : earliest(items),
      current: currentProject,
      runs: items,
    };
  });

  groups.sort((a, b) => {
    if (a.current !== b.current) return a.current ? -1 : 1;
    return (b.connectedAt ?? "").localeCompare(a.connectedAt ?? "");
  });
  return groups;
}

function earliest(runs: RunRecord[]) {
  return runs.reduce<string | null>((found, run) => {
    if (!run.createdAt) return found;
    if (!found || run.createdAt < found) return run.createdAt;
    return found;
  }, null);
}

function stamp(run: RunRecord) {
  return run.finishedAt || run.startedAt || run.createdAt || "";
}

export const PROJECT_DISCONNECTED =
  "This project was disconnected, so this run was stopped. It cannot be continued.";

export async function stopProjectRuns(userId: string, projectId: string) {
  const firestore = db();
  const snap = await firestore
    .collection(COLLECTIONS.RUNS)
    .where("userId", "==", userId)
    .get();
  const targets = snap.docs.filter((doc) => {
    const status = doc.get("status");
    return (
      doc.get("projectId") === projectId &&
      (status === "queued" || status === "running" || status === "blocked")
    );
  });

  const userRef = firestore.collection(COLLECTIONS.USERS).doc(userId);
  if (targets.length === 0) {
    await userRef.update({
      activeRunId: null,
      updatedAt: FieldValue.serverTimestamp(),
    });
    return;
  }

  for (let index = 0; index < targets.length; index += 400) {
    const batch = firestore.batch();
    for (const doc of targets.slice(index, index + 400)) {
      batch.update(doc.ref, {
        status: "failed",
        error: PROJECT_DISCONNECTED,
        finishedAt: FieldValue.serverTimestamp(),
      });
    }
    if (index === 0) {
      batch.update(userRef, {
        activeRunId: null,
        updatedAt: FieldValue.serverTimestamp(),
      });
    }
    await batch.commit();
  }
}

